1	import { profileWithFacts } from "./gen-profiles.js";
2	import { fillPlaceholders } from "../sim/facts.js";
3	import { writeFileSync, readFileSync, existsSync } from "node:fs";
4	import { fileURLToPath } from "node:url";
5	import path from "node:path";
6	
7	const here = path.dirname(fileURLToPath(import.meta.url));
8	const OUT_PATH = path.join(here, "training-data.jsonl");
9	
10	const GEMINI_KEY = process.env.GEMINI_API_KEY;
11	if (!GEMINI_KEY) {
12	  console.error("Set GEMINI_API_KEY in .env or environment");
13	  process.exit(1);
14	}
15	
16	const QUESTIONS = [
17	  "Did we ever buy a house?",
18	  "Was I okay with money?",
19	  "How much did I save by the time I was seventy?",
20	  "Did I retire early?",
21	  "What's my retirement income like?",
22	  "Will my money last?",
23	  "How's my health?",
24	  "How long do I live?",
25	  "Am I healthy in my old age?",
26	  "What's the one thing I should change?",
27	  "Should I save more?",
28	  "What if I exercised more?",
29	  "Do I regret not saving earlier?",
30	  "What about my sleep habits?",
31	  "Is smoking really that bad for me?",
32	  "How much should I be putting away each month?",
33	  "What does my retirement look like?",
34	  "Am I going to be comfortable?",
35	  "What would you tell younger me?",
36	  "Did the saving pay off?",
37	  "How are my healthy years?",
38	  "What's the chance my money lasts to ninety?",
39	  "Should I cut back on drinking?",
40	  "What if I quit smoking?",
41	  "Tell me about my finances at seventy.",
42	  "What's the best thing I can do right now?",
43	  "How do my habits affect my health?",
44	  "What does the typical outcome look like for someone like me?",
45	  "Am I saving enough?",
46	  "What would happen if I saved fifty more a month?",
47	];
