102	// Sanity bounds — reject values outside plausible ranges
103	const BOUNDS = {
104	  cpp_max_monthly: [1000, 2500],
105	  oas_max_monthly: [500, 1500],
106	  tfsa_annual_limit: [5000, 15000],
107	  rrsp_annual_max: [25000, 50000],
108	};
