179	export function simulate(inputFields, { numLives = 5000 } = {}) {
180	  const input = merge(DEFAULTS, inputFields || {});
181	  const core = runLives(input, numLives);
182	
183	  const facts = {
184	    ...core,
185	    apparent_age_at_70: 70,
186	    one_change: null,
187	    sources: [
188	      { value: "life_tables", url: "https://www150.statcan.gc.ca/t1/tbl1/en/tv.action?pid=1310011401", fetched_at: "2026-11-21T00:00:00Z" },
189	      { value: "cpp_max", url: "https://www.canada.ca/en/services/benefits/publicpensions/cpp.html", fetched_at: "2026-11-21T00:00:00Z" },
190	      { value: "oas_max", url: "https://www.canada.ca/en/services/benefits/publicpensions/cpp/old-age-security.html", fetched_at: "2026-11-21T00:00:00Z" },
191	      { value: "tfsa_limit", url: "https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/tax-free-savings-account.html", fetched_at: "2026-11-21T00:00:00Z" },
192	      { value: "returns", url: "https://www.credit-suisse.com/about-us/en/reports-research/global-investment-returns-yearbook.html", fetched_at: "2026-11-21T00:00:00Z" },
193	    ],
194	  };
195	
196	  facts.one_change = rankBestChange(input, core);
197	
198	  const baseLE = input.sex === "female" ? 84 : 80;
199	  const leDiff = facts.life_expectancy.median - baseLE;
200	  facts.apparent_age_at_70 = Math.round(70 - leDiff * 0.3);
201	
202	  return facts;
203	}
204	
205	const SLIDER_NUDGES = [
206	  { slider: "saving_per_month", nudge: (input) => ({ ...input, saving_per_month: input.saving_per_month + 50 }), label: (input) => `saving $${input.saving_per_month + 50 - input.saving_per_month} more a month` },
207	  { slider: "exercise_per_week", nudge: (input) => ({ ...input, habits: { ...input.habits, exercise_per_week: Math.min(input.habits.exercise_per_week + 2, 7) } }), label: () => "exercising twice more a week" },
208	  { slider: "sleep_hours", nudge: (input) => ({ ...input, habits: { ...input.habits, sleep_hours: 7.5 } }), label: () => "getting seven to eight hours of sleep" },
209	  { slider: "smoker", nudge: (input) => ({ ...input, habits: { ...input.habits, smoker: false } }), label: () => "quitting smoking" },
210	];
211	
212	function rankBestChange(input, baseFacts) {
213	  let best = null;
214	  let bestScore = 0;
215	
216	  for (const { slider, nudge, label } of SLIDER_NUDGES) {
217	    const nudged = nudge(input);
218	    if (JSON.stringify(nudged) === JSON.stringify(input)) continue;
219	
220	    const nudgedFacts = runLives(merge(DEFAULTS, nudged), 1000);
221	    const savingsGain = nudgedFacts.savings_70.median - baseFacts.savings_70.median;
222	    const yearsGain = nudgedFacts.life_expectancy.median - baseFacts.life_expectancy.median;
223	    const score = savingsGain / 50000 + yearsGain;
224	
225	    if (score > bestScore) {
226	      bestScore = score;
227	      best = { slider, label: label(input) };
228	    }
229	  }
230	
231	  return best || { slider: "saving_per_month", label: "saving $50 more a month" };
232	}
