4	export function createMirrorSession(url) {
5	  for (const [key, grant] of grants) if (grant.expires <= Date.now()) grants.delete(key);
6	  if (grants.size >= 2000) throw new Error("Mirror sessions full");
7	  const producer = randomBytes(24).toString("hex"), viewer = randomBytes(24).toString("hex");
8	  const room = { opened:false, expires:Date.now() + 2 * 60 * 60000 };
9	  grants.set(producer, {role:"producer", room, expires:room.expires});
10	  grants.set(viewer, {role:"viewer", room, expires:room.expires});
11	  const source = new URL(url), target = new URL(url);
12	  source.searchParams.delete("spectate");
13	  source.searchParams.set("mirror", producer);
14	  target.searchParams.set("mirror", viewer);
15	  target.searchParams.set("spectate", "1");
16	  return {room, watchToken:viewer, url:source.pathname + source.search, viewerUrl:target.pathname + target.search};
17	}
18	export function mirrorAccess(token) {
19	  const grant = typeof token === "string" && grants.get(token);
20	  return grant && grant.expires > Date.now() ? grant : null;
21	}
