1	// The /voice WebSocket (CONTRACTS.md "Voice pipeline").
2	//
3	// Built:
4	//   client -> {type:"start", name, sex, apparent_age}   begins a session; we greet by name
5	//   client -> {type:"text", question}                   a typed or confirmed question
6	//   client -> {type:"age", apparent_age}                slider moved; next sentences use it
7	//   server -> {type:"reply", sentence, audio, sampleRate, done}   one per sentence (+ ms: delay)
8	//   server -> {type:"status", state}                    listening | thinking | speaking
9	//   server -> {type:"error", feature, message}
10	//   reply.audio is null when the voice is off: the headset shows text only (text fallback).
11	//   client -> {type:"audio", data, sampleRate}         mic audio (16-bit mono PCM, 16000 Hz) streamed continuously
12	//   server -> {type:"transcript", text}                what the person said, sent when they stop talking
13	// Mic audio is dropped while the future self is still talking (plus a short tail), so the
14	// headset's mic can't hear the speakers and make Uncle answer itself.
15	import { mirrorAccess } from "./mirror-sessions.js";
16	import { WebSocketServer } from "ws";
17	import { speak as realSpeak } from "../voice/tts.js";
18	import { applyAging } from "../voice/filter.js";
19	import { agingParams, strengthForAge } from "../voice/aging.js";
20	import { floatToPcm16 } from "../voice/wav.js";
21	import { createStore } from "../voice/store.js";
22	import { createSttSession } from "../voice/stt.js";
23	import { loadSamples, clipFor } from "../voice/samples.js";
24	import { getFacts as realGetFacts } from "../sim/facts.js";
25	import { reply, replyStream, greeting } from "./brain.js";
26	import { chartForReply } from "./charts.js";
27	
28	const SPEAK_TIMEOUT_MS = 4000;
29	const MAX_QUESTION = 500;
30	
31	function send(ws, obj) {
32	  const data = JSON.stringify(obj);
33	  if (ws.readyState !== ws.OPEN) return;
34	  ws.send(data);
35	  if (ws.mirrorHistory) {
36	    ws.mirrorHistory.push(data);
37	    while (ws.mirrorHistory.length > 8 || ws.mirrorHistory.reduce((n,item)=>n+item.length,0) > 262144) ws.mirrorHistory.shift();
38	  }
39	  for (const peer of ws.mirrorViewers ?? []) {
40	    if (peer.readyState === peer.OPEN && peer.bufferedAmount < 4 * 1024 * 1024) peer.send(data);
41	  }
42	}
43	
44	// The simulation's merge lets a nested null overwrite one of its defaults (for example
45	// habits.drinks_per_week: null), so send it only the fields the person actually gave us.
46	export function dropNulls(obj) {
47	  if (Array.isArray(obj) || obj === null || typeof obj !== "object") return obj;
48	  const out = {};
49	  for (const [k, v] of Object.entries(obj)) {
50	    if (v === null || v === undefined) continue;
51	    const cleaned = dropNulls(v);
52	    if (cleaned !== null && typeof cleaned === "object" && !Array.isArray(cleaned) && Object.keys(cleaned).length === 0) continue;
53	    out[k] = cleaned;
54	  }
55	  return out;
56	}
57	
58	const clampAge = (n) => (Number.isFinite(Number(n)) ? Math.min(100, Math.max(20, Number(n))) : null);
59	
60	export function attachVoice(httpServer, { speakFn = realSpeak, getFacts = realGetFacts, store = createStore(), sttFactory = createSttSession, writeFn, samples = loadSamples(), streamReplies = process.env.STREAM_REPLY === "1" } = {}) {
61	  const wss = new WebSocketServer({ server: httpServer, path: "/voice", maxPayload: 4 * 1024 * 1024 });
62	
63	  const rooms = new Map();
64	  wss.on("connection", (ws) => {
65	    let mirrorRoom = null;
66	    function joinMirror(token, role) {
67	      const grant = mirrorAccess(token);
68	      if (!grant || grant.role !== role || mirrorRoom) return false;
69	      if (!rooms.has(grant.room)) rooms.set(grant.room, {viewers:new Set(), producer:null, history:[]});
70	      mirrorRoom = rooms.get(grant.room);
71	      if (role === "viewer") { mirrorRoom.viewers.add(ws); ws.isMirrorViewer = true; }
72	      else {
73	        if (mirrorRoom.producer && mirrorRoom.producer !== ws) mirrorRoom.producer.close();
74	        grant.room.opened = true;
75	        mirrorRoom.producer = ws; ws.mirrorViewers = mirrorRoom.viewers; ws.mirrorHistory = mirrorRoom.history;
76	      }
77	      return true;
78	    }
79	    ws.on("close", () => {
80	      if (!mirrorRoom) return;
81	      mirrorRoom.viewers.delete(ws);
82	      if (mirrorRoom.producer === ws) mirrorRoom.producer = null;
83	      if (!mirrorRoom.producer && !mirrorRoom.viewers.size) {
84	        for (const [key, value] of rooms) if (value === mirrorRoom) rooms.delete(key);
85	      }
86	    });
87	    // What we know about this person, set by the "start" message.
88	    const session = { name: null, sex: "neutral", apparentAge: null, voiceId: undefined, facts: null, history: [], speech: "", profile: null };
89	    let queue = Promise.resolve(); // one reply at a time, in order
90	    let stt = null; // speech-to-text session, opened when mic audio first arrives
91	    let playbackUntil = 0; // when the headset will finish playing what we last sent (ms clock)
92	
93	    // Speak with the person's own clone; if that fails, fall back to the stock voice so the
94	    // conversation keeps going (PLAN.md: "if cloning fails, a ready-made voice, then text").
95	    // A slow ElevenLabs call must not stall the conversation: after SPEAK_TIMEOUT_MS give up on the clone.
96	    const withTimeout = (promise, ms, what) =>
97	      Promise.race([promise, new Promise((_, reject) => setTimeout(() => reject(new Error(`${what} took longer than ${ms} ms`)), ms).unref())]);
98	    async function speakOne(sentence) {
99	      try {
100	        try {
101	          return await withTimeout(speakFn(sentence, { voiceId: session.voiceId }), SPEAK_TIMEOUT_MS, "voice");
102	        } catch (err) {
103	          if (!session.voiceId) throw err;
104	          return await withTimeout(speakFn(sentence, {}), SPEAK_TIMEOUT_MS, "stock voice");
105	        }
106	      } catch (err) {
107	        // The speech service is down or out of credits: play a pre-recorded line if we have one, else text only.
108	        const clip = clipFor(samples, sentence);
109	        if (!clip) throw err;
110	        return { samples: clip.samples, sampleRate: clip.sampleRate, clipText: clip.text };
111	      }
112	    }
113	
114	    // Sends one sentence (waiting for its speech job), aged, in order. Shared by the batch and streaming paths.
115	    function makeEmitter(meta) {
116	      const started = performance.now();
117	      const facts = session.facts ?? getFacts();
118	      const strength = strengthForAge(session.apparentAge ?? facts.apparent_age_at_70);
119	      let reportedError = false;
120	      let spoke = false;
121	      let n = 0;
122	      return async (sentence, job, done) => {
123	        const { tts, error } = await job;
124	        let audio = null;
125	        let sampleRate = 24000;
126	        if (tts) {
127	          const aged = applyAging(tts.samples, tts.sampleRate, agingParams(strength, session.sex));
128	          audio = floatToPcm16(aged).toString("base64");
129	          sampleRate = tts.sampleRate;
130	          if (tts.clipText && !reportedError) (reportedError = true), send(ws, { type: "error", feature: "voice", message: "live voice is unavailable; playing recorded lines where we have them" });
131	          if (!spoke) (spoke = true), send(ws, { type: "status", state: "speaking" });
132	          // Remember how long this will play, so mic audio during it is ignored (echo guard).
133	          playbackUntil = Math.max(playbackUntil, performance.now()) + (aged.length / tts.sampleRate) * 1000;
134	        } else if (!reportedError) {
135	          reportedError = true;
136	          send(ws, { type: "error", feature: "voice", message: error?.message ?? "voice failed" });
137	        }
138	        const first = n++ === 0;
139	        const m = typeof meta === "function" ? meta() : meta;
140	        send(ws, {
141	          type: "reply",
142	          sentence: tts?.clipText ?? sentence, // a recorded clip says its own words
143	          audio,
144	          sampleRate,
145	          done,
146	          ms: Math.round(performance.now() - started),
147	          ...(first && m ? { timing: { thinkMs: m.thinkMs, source: m.source } } : {}),
148	        });
149	        if (first && m) console.log(`[voice] reply: write ${m.thinkMs} ms (${m.source}${m.streamed ? ", streamed" : ""}), first sentence spoken ${Math.round(performance.now() - started)} ms later${session.voiceId ? " (clone)" : " (stock)"}`);
150	      };
151	    }
152	
153	    // Write the answer (model or Gemini, checked; keyword stand-in if that fails), remember the exchange, speak it.
154	    function sendChart(question, profile, facts) {
155	      const chart = chartForReply(question, profile, facts);
156	      if (chart) send(ws, { type: "chart", chart });
157	    }
158	
159	    async function respond(question) {
160	      send(ws, { type: "status", state: "thinking" });
161	      const facts = session.facts ?? getFacts();
162	      const t0 = performance.now();
163	      if (streamReplies) return respondStreaming(question, facts, t0);
164	      const { sentences, source } = await reply(question, facts, { history: session.history, name: session.name, speech: session.speech, writeFn });
165	      const thinkMs = Math.round(performance.now() - t0);
166	      sendChart(question, session.profile, facts);
167	      session.history.push({ role: "you", text: question }, { role: "future", text: sentences.join(" ") });
168	      session.history = session.history.slice(-12);
169	      return say(sentences, { thinkMs, source });
170	    }
171	
172	    // Streaming: each sentence is checked and starts being spoken the moment the model finishes writing it.
173	    // The reply ends with an empty sentence marked done (the count is not known until the model stops).
174	    async function respondStreaming(question, facts, t0) {
175	      let meta = null;
176	      const emit = makeEmitter(() => meta);
177	      const spoken = [];
178	      let chain = Promise.resolve();
179	      let chartSent = false;
180	      for await (const { sentence, source } of replyStream(question, facts, { history: session.history, name: session.name, speech: session.speech, writeFn })) {
181	        if (!meta) meta = { thinkMs: Math.round(performance.now() - t0), source, streamed: source === "model" };
182	        if (!chartSent) { chartSent = true; sendChart(question, session.profile, facts); }
183	        spoken.push(sentence);
184	        const job = speakOne(sentence).then((tts) => ({ tts }), (error) => ({ error }));
185	        chain = chain.then(() => emit(sentence, job, false));
186	      }
187	      await chain;
188	      send(ws, { type: "reply", sentence: "", audio: null, sampleRate: 24000, done: true });
189	      session.history.push({ role: "you", text: question }, { role: "future", text: spoken.join(" ") });
190	      session.history = session.history.slice(-12);
191	      send(ws, { type: "status", state: "listening" });
192	    }
193	
194	    async function say(sentences, meta) {
195	      send(ws, { type: "status", state: "thinking" });
196	      const emit = makeEmitter(meta);
197	      // Start every sentence's speech at once, then send in order: sentence 1 plays while 2 and 3 are made.
198	      const jobs = sentences.map((s) => speakOne(s).then((tts) => ({ tts }), (error) => ({ error })));
199	      for (let i = 0; i < sentences.length; i++) await emit(sentences[i], jobs[i], i === sentences.length - 1);
200	      send(ws, { type: "status", state: "listening" });
201	    }
202	
203	    function openStt() {
204	      try {
205	        stt = sttFactory({
206	          onTranscript: (text) => {
207	            send(ws, { type: "transcript", text });
208	            enqueue(() => respond(text));
209	          },
210	          onError: (message) => {
211	            stt = null;
212	            send(ws, { type: "error", feature: "speech-to-text", message });
213	          },
214	          onClose: () => {
215	            stt = null; // it closes itself after ~15 s with no audio; we reopen on the next chunk
216	          },
217	        });
218	      } catch (err) {
219	        stt = null;
220	        send(ws, { type: "error", feature: "speech-to-text", message: err.message });
221	      }
222	    }
223	
224	    const enqueue = (fn) => {
225	      queue = queue.then(fn).catch((err) => send(ws, { type: "error", feature: "voice", message: err.message }));
226	    };
227	
228	    send(ws, { type: "status", state: "listening" });
229	
230	    ws.on("close", () => stt?.close());
231	    ws.on("message", (raw) => {
232	      let msg;
233	      try {
234	        msg = JSON.parse(raw.toString());
235	      } catch {
236	        return send(ws, { type: "error", feature: "protocol", message: "messages must be JSON" });
237	      }
238	
239	      if (ws.isMirrorViewer) return;
240	      if (msg?.type === "watch") {
241	        if (!joinMirror(msg.mirror, "viewer")) return send(ws, {type:"error",feature:"mirror",message:"This mirror session expired."});
242	        send(ws, {type:"status",state:"listening"});
243	        for (const data of mirrorRoom.history) ws.send(data);
244	        return;
245	      }
246	      switch (msg?.type) {
247	        case "start": {
248	          if (msg.mirror && !joinMirror(msg.mirror, "producer")) return send(ws, {type:"error",feature:"mirror",message:"This mirror session expired."});
249	          session.name = String(msg.name ?? "").trim().slice(0, 40) || null;
250	          session.sex = ["male", "female"].includes(msg.sex) ? msg.sex : "neutral";
251	          session.apparentAge = clampAge(msg.apparent_age);
252	          session.voiceId = session.name ? store.find(session.name)?.voiceId : undefined;
253	          // If this person confirmed their interview answers, the simulation runs on THEIR numbers.
254	          // Otherwise the sample facts sheet is used.
255	          const saved = session.name ? store.getProfile(session.name) : null;
256	          session.facts = saved ? getFacts(dropNulls(saved.profile)) : null;
257	          session.profile = saved ? dropNulls(saved.profile) : null;
258	          session.speech = saved?.speech ?? "";
259	          if (session.sex === "neutral" && saved?.profile?.sex) session.sex = saved.profile.sex;
260	          const startFacts = session.facts ?? getFacts();
261	          send(ws, { type: "facts", apparent_age_at_70: startFacts.apparent_age_at_70 });
262	          enqueue(() => say(greeting(session.name)));
263	          break;
264	        }
265	        case "age": {
266	          const age = clampAge(msg.apparent_age);
267	          if (age === null) return send(ws, { type: "error", feature: "protocol", message: "apparent_age must be a number" });
268	          session.apparentAge = age;
269	          break;
270	        }
271	        case "slider": {
272	          const SLIDERS = { saving_per_month: "number", exercise_per_week: "number", sleep_hours: "number", smoker: "boolean" };
273	          const sName = String(msg.name ?? "");
274	          if (!(sName in SLIDERS)) return send(ws, { type: "error", feature: "protocol", message: "unknown slider: " + sName });
275	          if (!session.profile) return send(ws, { type: "error", feature: "protocol", message: "no profile saved for this session" });
276	          const val = SLIDERS[sName] === "boolean" ? Boolean(msg.value) : Number(msg.value);
277	          if (SLIDERS[sName] === "number" && !Number.isFinite(val)) return send(ws, { type: "error", feature: "protocol", message: "value must be a number" });
278	          const updated = { ...session.profile };
279	          if (sName === "saving_per_month") updated.saving_per_month = val;
280	          else updated.habits = { ...updated.habits, [sName]: val };
281	          session.profile = updated;
282	          session.facts = getFacts(dropNulls(updated));
283	          send(ws, { type: "facts", apparent_age_at_70: session.facts.apparent_age_at_70 });
284	          sendChart("What should I change?", session.profile, session.facts);
285	          break;
286	        }
287	        case "text": {
288	          const question = String(msg.question ?? "").trim().slice(0, MAX_QUESTION);
289	          if (!question) return send(ws, { type: "error", feature: "protocol", message: "question is empty" });
290	          enqueue(() => respond(question));
291	          break;
292	        }
293	        case "audio": {
294	          if (typeof msg.data !== "string" || !msg.data) break;
295	          if (performance.now() < playbackUntil + 300) break; // echo guard: Uncle is still talking
296	          if (!stt) openStt();
297	          stt?.send(msg.data, Number(msg.sampleRate) || 16000);
298	          break;
299	        }
300	        default:
301	          break; // unknown types are ignored, so newer clients don't break older servers
302	      }
303	    });
304	  });
305	
306	  return wss;
307	}
