1	// Plays reply sentences back to back (no gaps) and exposes an analyser the mouth reads.
2	import { decodePcm16 } from "./pcm.js";
3	
4	export function nextStartTime(now, queuedUntil) {
5	  return Math.max(now, queuedUntil);
6	}
7	
8	export function createPlayer() {
9	  let ctx = null;
10	  let analyser = null;
11	  let output = null;
12	  let muted = false;
13	  let queuedUntil = 0;
14	  let silent = [];
15	  const now = () => muted ? performance.now() / 1000 : ctx ? ctx.currentTime : 0;
16	  const buf = new Float32Array(1024);
17	
18	  function ensure() {
19	    if (ctx) return;
20	    ctx = new AudioContext();
21	    analyser = ctx.createAnalyser();
22	    analyser.fftSize = 1024;
23	    output = ctx.createGain();
24	    output.gain.value = muted ? 0 : 1;
25	    analyser.connect(output);
26	    output.connect(ctx.destination);
27	  }
28	
29	  return {
30	    setMuted(value) { muted = value; queuedUntil = 0; silent = []; if (output) output.gain.value = value ? 0 : 1; },
31	    // Call from a user gesture (Start button) so the browser allows audio.
32	    async unlock() {
33	      if (muted) return;
34	      ensure();
35	      if (ctx.state !== "running") await ctx.resume();
36	    },
37	    // Queue one contract reply's audio. Returns the time (s, context clock) it starts.
38	    enqueue(base64, sampleRate) {
39	      const samples = decodePcm16(base64);
40	      if (muted) {
41	        const start = nextStartTime(now(), queuedUntil);
42	        queuedUntil = start + samples.length / sampleRate;
43	        silent.push({samples,sampleRate,start,end:queuedUntil});
44	        return {start,end:queuedUntil};
45	      }
46	      ensure();
47	      const audio = ctx.createBuffer(1, samples.length, sampleRate);
48	      audio.copyToChannel(samples, 0);
49	      const src = ctx.createBufferSource();
50	      src.buffer = audio;
51	      src.connect(analyser);
52	      const start = nextStartTime(ctx.currentTime, queuedUntil);
53	      src.start(start);
54	      queuedUntil = start + audio.duration;
55	      return { start, end: queuedUntil };
56	    },
57	    // Latest audio frame being played, for mouth analysis. Null before audio exists.
58	    frame() {
59	      if (muted) {
60	        const time = now();
61	        silent = silent.filter(item => item.end > time);
62	        const item = silent.find(item => item.start <= time);
63	        if (!item) return null;
64	        const offset = Math.floor((time - item.start) * item.sampleRate);
65	        buf.fill(0); buf.set(item.samples.subarray(offset, offset + buf.length));
66	        return {samples:buf,sampleRate:item.sampleRate};
67	      }
68	      if (!analyser) return null;
69	      analyser.getFloatTimeDomainData(buf);
70	      return { samples: buf, sampleRate: ctx.sampleRate };
71	    },
72	    now() {
73	      return now();
74	    },
75	    speaking() {
76	      return now() < queuedUntil;
77	    },
78	  };
79	}
80

