26	    ws.onmessage = (e) => {
27	      const m = JSON.parse(e.data);
28	      got.push(m);
29	      if (until(m)) (clearTimeout(timer), ws.close(), resolve(got));
30	    };
31	    ws.onerror = () => reject(new Error("socket error"));
