102	// Collect everything until the server goes back to "listening" after replying.
103	function session(url, messages, repliesWanted = 1) {
104	  return new Promise((resolve, reject) => {
105	    const ws = new WebSocket(url);
106	    const got = [];
107	    let finished = 0;
108	    const timer = setTimeout(() => (ws.close(), reject(new Error("timed out"))), 5000);
109	    ws.onopen = () => messages.forEach((m) => ws.send(JSON.stringify(m)));
110	    ws.onmessage = (e) => {
111	      const m = JSON.parse(e.data);
112	      got.push(m);
113	      if (m.type === "reply" && m.done) finished++;
114	      if (finished >= repliesWanted && m.type === "status" && m.state === "listening") (clearTimeout(timer), ws.close(), resolve(got));
115	    };
116	    ws.onerror = () => reject(new Error("socket error"));
117	  });
118	}
