207	function fakeStt() {
208	  const made = [];
209	  const factory = (cbs) => {
210	    const s = { cbs, chunks: [], closed: false, send(b64, rate) { this.chunks.push([b64, rate]); return true; }, close() { this.closed = true; } };
211	    made.push(s);
212	    return s;
213	  };
214	  return { factory, made };
215	}
216	const wait = (ms) => new Promise((r) => setTimeout(r, ms));
217	function openSocket(url) {
218	  return new Promise((resolve, reject) => {
219	    const ws = new WebSocket(url);
220	    const got = [];
221	    ws.onmessage = (e) => got.push(JSON.parse(e.data));
222	    ws.onopen = () => resolve({ ws, got });
223	    ws.onerror = () => reject(new Error("socket error"));
224	  });
225	}
