334	import http from "node:http";
335	import { resetModelBreaker } from "../voice/chat.js";
336	
337	// A fake vLLM: sends the reply as server-sent events, with a pause before the last piece.
338	function fakeModel(pieces, { pauseMs = 300, status = 200 } = {}) {
339	  const server = http.createServer((req, res) => {
340	    req.resume();
341	    if (status !== 200) return res.writeHead(status).end("nope");
342	    res.writeHead(200, { "content-type": "text/event-stream" });
343	    const emit = (c) => res.write(`data: ${JSON.stringify({ choices: [{ delta: { content: c } }] })}\n\n`);
344	    pieces.slice(0, -1).forEach(emit);
345	    setTimeout(() => (emit(pieces.at(-1)), res.write("data: [DONE]\n\n"), res.end()), pauseMs);
346	  });
347	  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve({ server, url: `http://127.0.0.1:${server.address().port}` })));
348	}
