350	async function withModel(model, fn) {
351	  const oldFirst = process.env.MODEL_FIRST;
352	  process.env.MODEL_FIRST = "1";
353	  const old = process.env.MODEL_URL;
354	  process.env.MODEL_URL = model.url;
355	  resetModelBreaker();
356	  try {
357	    await fn();
358	  } finally {
359	    old === undefined ? delete process.env.MODEL_URL : (process.env.MODEL_URL = old);
360	    oldFirst === undefined ? delete process.env.MODEL_FIRST : (process.env.MODEL_FIRST = oldFirst);
361	    resetModelBreaker();
362	    model.server.close();
363	  }
364	}
