case "audio": {
  if (typeof msg.data !== "string" || !msg.data) break;
  // If Uncle is still talking but the user starts speaking, interrupt: stop sending
  // remaining sentences and switch to listening. The echo guard stays for the first
  // 300ms after the last sent audio to avoid picking up speaker bleed.
  if (performance.now() < playbackUntil + 300) {
    // User is trying to talk while Uncle speaks — signal interruption
    interrupted = true;
    playbackUntil = 0; // stop the echo guard so their speech goes through
    send(ws, { type: "status", state: "listening" });
  }
  if (!stt) openStt();
  stt?.send(msg.data, Number(msg.sampleRate) || 16000);
  break;
}

